                throw new ArgumentNullException(nameof(recommendationItem.ResolvedSourceRefs), "Property is required for class RecommendationItem.");

            if (recommendationItem.UnresolvedSourceRefsOption.IsSet && recommendationItem.UnresolvedSourceRefs == null)
                throw new ArgumentNullException(nameof(recommendationItem.UnresolvedSourceRefs), "Property is required for class RecommendationItem.");

            writer.WriteNumber("id", recommendationItem.Id);

            writer.WriteNumber("recommendation_id", recommendationItem.RecommendationId);

            writer.WriteString("recommendation_type", recommendationItem.RecommendationType);

            writer.WriteString("category", recommendationItem.Category);

            writer.WriteString("title", recommendationItem.Title);

            var priorityRawValue = RecommendationItem.PriorityEnumToJsonValue(recommendationItem.Priority);
            writer.WriteString("priority", priorityRawValue);
            writer.WritePropertyName("action_items");
            JsonSerializer.Serialize(writer, recommendationItem.ActionItems, jsonSerializerOptions);
            writer.WritePropertyName("source_refs");
            JsonSerializer.Serialize(writer, recommendationItem.SourceRefs, jsonSerializerOptions);
            var statusRawValue = RecommendationItem.StatusEnumToJsonValue(recommendationItem.Status);
            writer.WriteString("status", statusRawValue);
            writer.WriteNumber("position", recommendationItem.Position);

            writer.WriteString("created_at", recommendationItem.CreatedAt.ToString(CreatedAtFormat));

            writer.WriteString("updated_at", recommendationItem.UpdatedAt.ToString(UpdatedAtFormat));

            if (recommendationItem.DescriptionOption.IsSet)
                if (recommendationItem.DescriptionOption.Value != null)
                    writer.WriteString("description", recommendationItem.Description);
                else
                    writer.WriteNull("description");

            if (recommendationItem.EstimatedImpactOption.IsSet)
                if (recommendationItem.EstimatedImpactOption.Value != null)
                    writer.WriteString("estimated_impact", recommendationItem.EstimatedImpact);
                else
                    writer.WriteNull("estimated_impact");

            if (recommendationItem.StatusChangedAtOption.IsSet)
                if (recommendationItem.StatusChangedAtOption.Value != null)
                    writer.WriteString("status_changed_at", recommendationItem.StatusChangedAtOption.Value!.Value.ToString(StatusChangedAtFormat));
                else
                    writer.WriteNull("status_changed_at");

            if (recommendationItem.MetadataOption.IsSet)
            {
                writer.WritePropertyName("metadata");
                JsonSerializer.Serialize(writer, recommendationItem.Metadata, jsonSerializerOptions);
            }
            if (recommendationItem.ResolvedSourceRefsOption.IsSet)
            {
                writer.WritePropertyName("resolved_source_refs");
                JsonSerializer.Serialize(writer, recommendationItem.ResolvedSourceRefs, jsonSerializerOptions);
            }
            if (recommendationItem.UnresolvedSourceRefsOption.IsSet)
            {
                writer.WritePropertyName("unresolved_source_refs");
                JsonSerializer.Serialize(writer, recommendationItem.UnresolvedSourceRefs, jsonSerializerOptions);
            }
        }
    }
